insert into public.learning_topics(skill_id,code,name,description,sequence_no,status) select sk.id,t.code,t.name,t.description,t.seq,'active' from public.learning_subjects s join public.learning_skills sk on sk.subject_id=s.id join (values
('BIO','M2-RESP','M2-RESP,Respiratory System','Thai M2 Science biological-science strand topic.',1),
('BIO','M2-EXCRET','M2-EXCRET,Excretory System','Thai M2 Science biological-science strand topic.',2),
('BIO','M2-CIRC','M2-CIRC,Circulatory System','Thai M2 Science biological-science strand topic.',3),
('BIO','M2-NERVE','M2-NERVE,Nervous System','Thai M2 Science biological-science strand topic.',4),
('BIO','M2-REPRO','M2-REPRO,Human Reproductive System','Thai M2 Science biological-science strand topic.',5),
('BIO','M3-GENE','M3-GENE,Genetics','Thai M3 Science biological-science strand topic.',6),
('BIO','M3-BIOTECH','M3-BIOTECH,Biotechnology','Thai M3 Science biological-science strand topic.',7),
('BIO','M3-BIODIV','M3-BIODIV,Biodiversity','Thai M3 Science biological-science strand topic.',8)) as t(skill_code,code,name,description,seq) on true where s.code='SCI' and sk.code=t.skill_code on conflict(skill_id,code) do update set name=excluded.name,description=excluded.description,sequence_no=excluded.sequence_no,status='active',updated_at=now();
insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status) select tp.id,o.code,o.name,o.description,o.seq,'active' from public.learning_subjects s join public.learning_skills sk on sk.subject_id=s.id join (values
('M2-RESP','M2-S1_2-01','Identify respiratory organs','Identify respiratory organs and describe their functions.',1),
('M2-RESP','M2-S1_2-02','Explain breathing and gas exchange','Explain inhalation, exhalation and gas exchange.',2),
('M2-RESP','M2-S1_2-03','Care for the respiratory system','Explain respiratory health and ways to protect the lungs.',3),
('M2-EXCRET','M2-S1_2-04','Describe the urinary system','Identify urinary organs and explain how kidneys filter blood.',4),
('M2-EXCRET','M2-S1_2-05','Maintain kidney health','Explain kidney health and responsible health behaviours.',5),
('M2-CIRC','M2-S1_2-06','Describe heart, blood vessels and blood','Describe structures and functions of the heart, blood vessels and blood.',6),
('M2-CIRC','M2-S1_2-07','Model blood circulation','Explain how circulation transports substances around the body.',7),
('M2-CIRC','M2-S1_2-08','Investigate heart rate','Plan a fair investigation of heart rate before and after activity.',8),
('M2-CIRC','M2-S1_2-09','Care for the circulatory system','Explain circulatory health and preventive behaviours.',9),
('M2-NERVE','M2-S1_2-10','Describe the central nervous system','Identify the brain and spinal cord and explain their roles.',10),
('M2-NERVE','M2-S1_2-11','Protect the nervous system','Explain the importance of protecting the brain and spinal cord.',11),
('M2-REPRO','M2-S1_2-12','Identify reproductive organs','Identify male and female reproductive organs and their functions.',12),
('M2-REPRO','M2-S1_2-13','Explain sex hormones','Explain how sex hormones contribute to puberty.',13),
('M2-REPRO','M2-S1_2-14','Understand puberty and personal care','Explain puberty changes and healthy physical and mental care.',14),
('M2-REPRO','M2-S1_2-15','Explain the menstrual cycle and early development','Explain ovulation, menstruation, fertilisation and early embryo development.',15),
('M2-REPRO','M2-S1_2-16','Compare contraception methods','Select contraception using reliable health information.',16),
('M2-REPRO','M2-S1_2-17','Recognise impacts of adolescent pregnancy','Explain potential impacts and identify responsible sources of support.',17),
('M3-GENE','M3-S1_3-01','Relate genes, DNA and chromosomes','Explain relationships among genes, DNA and chromosomes.',18),
('M3-GENE','M3-S1_3-02','Explain dominant and recessive inheritance','Explain single-character inheritance with complete dominance.',19),
('M3-GENE','M3-S1_3-03','Calculate inheritance ratios','Determine offspring genotypes and phenotypes for a single-gene cross.',20),
('M3-GENE','M3-S1_3-04','Compare mitosis and meiosis','Compare cell division processes and their roles.',21),
('M3-GENE','M3-S1_3-05','Explain genetic disorders','Explain how gene or chromosome changes can cause genetic disorders.',22),
('M3-GENE','M3-S1_3-06','Recognise genetic counselling','Explain how consultation and testing can help assess inherited risks.',23),
('M3-BIOTECH','M3-S1_3-07','Explain uses of genetically modified organisms','Describe applications of genetic modification in organisms.',24),
('M3-BIOTECH','M3-S1_3-08','Evaluate GMO benefits and impacts','Communicate evidence-based benefits and possible impacts of GMOs.',25),
('M3-BIODIV','M3-S1_3-09','Compare biodiversity among ecosystems','Compare species diversity using observations or data.',26),
('M3-BIODIV','M3-S1_3-10','Explain the importance of biodiversity','Explain how biodiversity supports ecosystems and people.',27),
('M3-BIODIV','M3-S1_3-11','Conserve biodiversity','Propose or participate in practical biodiversity conservation.',28)) as o(topic_code,code,name,description,seq) on true join public.learning_topics tp on tp.skill_id=sk.id and tp.code=o.topic_code where s.code='SCI' and sk.code='BIO' on conflict(topic_id,code) do update set name=excluded.name,description=excluded.description,sequence_no=excluded.sequence_no,status='active',updated_at=now();
insert into public.learning_objective_alignments(objective_id,curriculum_id,grade_level_id,sequence_no,required,notes) select ob.id,c.id,g.id,a.seq,true,'Thailand Basic Education Core Curriculum B.E. 2551 (2008), revised B.E. 2560 (2017); official indicator '||a.indicator||'.' from (values
('M2-S1_2-01',1,'ว 1.2 ม.2/1','M2'),
('M2-S1_2-02',2,'ว 1.2 ม.2/2','M2'),
('M2-S1_2-03',3,'ว 1.2 ม.2/3','M2'),
('M2-S1_2-04',4,'ว 1.2 ม.2/4','M2'),
('M2-S1_2-05',5,'ว 1.2 ม.2/5','M2'),
('M2-S1_2-06',6,'ว 1.2 ม.2/6','M2'),
('M2-S1_2-07',7,'ว 1.2 ม.2/7','M2'),
('M2-S1_2-08',8,'ว 1.2 ม.2/8','M2'),
('M2-S1_2-09',9,'ว 1.2 ม.2/9','M2'),
('M2-S1_2-10',10,'ว 1.2 ม.2/10','M2'),
('M2-S1_2-11',11,'ว 1.2 ม.2/11','M2'),
('M2-S1_2-12',12,'ว 1.2 ม.2/12','M2'),
('M2-S1_2-13',13,'ว 1.2 ม.2/13','M2'),
('M2-S1_2-14',14,'ว 1.2 ม.2/14','M2'),
('M2-S1_2-15',15,'ว 1.2 ม.2/15','M2'),
('M2-S1_2-16',16,'ว 1.2 ม.2/16','M2'),
('M2-S1_2-17',17,'ว 1.2 ม.2/17','M2'),
('M3-S1_3-01',18,'ว 1.3 ม.3/1','M3'),
('M3-S1_3-02',19,'ว 1.3 ม.3/2','M3'),
('M3-S1_3-03',20,'ว 1.3 ม.3/3','M3'),
('M3-S1_3-04',21,'ว 1.3 ม.3/4','M3'),
('M3-S1_3-05',22,'ว 1.3 ม.3/5','M3'),
('M3-S1_3-06',23,'ว 1.3 ม.3/6','M3'),
('M3-S1_3-07',24,'ว 1.3 ม.3/7','M3'),
('M3-S1_3-08',25,'ว 1.3 ม.3/8','M3'),
('M3-S1_3-09',26,'ว 1.3 ม.3/9','M3'),
('M3-S1_3-10',27,'ว 1.3 ม.3/10','M3'),
('M3-S1_3-11',28,'ว 1.3 ม.3/11','M3')) as a(code,seq,indicator,grade_code) join public.learning_objectives ob on ob.code=a.code join public.learning_topics tp on tp.id=ob.topic_id join public.learning_skills sk on sk.id=tp.skill_id join public.learning_subjects s on s.id=sk.subject_id and s.code='SCI' join public.learning_curricula c on c.code='TH-SCI-M1-M6' join public.learning_grade_levels g on g.curriculum_id=c.id and g.code=a.grade_code on conflict(objective_id,curriculum_id,grade_level_id) do update set sequence_no=excluded.sequence_no,required=excluded.required,notes=excluded.notes,updated_at=now();
