-- E&P Learning: M2 and M3 Science biological-science knowledge graph.
-- Official Thai Basic Education indicators, revised B.E. 2560 (2017): ว 1.2 (M2) and ว 1.3 (M3).
-- Staged release: other M2/M3 standards will be seeded in subsequent migrations.
-- Technology standards ว 4.1/ว 4.2 remain reserved for Design & Technology / Computer Studies.
begin;
do $$ begin if not exists (select 1 from public.learning_subjects s join public.learning_curricula c on c.code='TH-SCI-M1-M6' join public.learning_education_systems es on es.id=c.education_system_id join public.learning_grade_levels g on g.curriculum_id=c.id and g.code in ('M2','M3') where s.code='SCI' and es.code='TH_BASIC' and s.status='active' and c.status='active' and g.status='active') then raise exception 'Active SCI curriculum and M2/M3 grades are required.'; end if; end $$;
commit;
